fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // If you want to enforce that the two input vectors have the same length:
    debug_assert!(
        a.len() == b.len(),
        "Input vectors must have the same length"
    );

    // Zip the two vectors together, compare element-wise, and collect the booleans
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x < y)
        .collect()
}

